import assert from "node:assert/strict";
import test from "node:test";

import {
  BuildSheafChatStaticRoots,
  BuildVendorAssetAllowlist,
  ResolveSheafChatIndexPath,
  ResolveStaticFile,
  x_aguiChatCssPath,
  x_aguiChatJsPath,
  x_katexCssPath,
  x_katexFontsUrlPrefix,
  x_katexJsPath,
  x_markdownItJsPath,
  x_sheafChatCssPath,
  x_sheafChatJsPath,
  x_sheafMarkdownJsPath,
} from "../../src/server/static.js";
import { FindRepositoryRoot } from "../../src/server/repo_paths.js";
import { StartTestServer } from "./rest/helpers.js";

test("static roots resolve bundled UI and shared AGUI assets", () =>
{
  const repoRoot = FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  const roots = BuildSheafChatStaticRoots(repoRoot);
  const aguiJs = ResolveStaticFile(x_aguiChatJsPath, roots);
  const aguiCss = ResolveStaticFile(x_aguiChatCssPath, roots);
  const sheafCss = ResolveStaticFile(x_sheafChatCssPath, roots);
  const sheafJs = ResolveStaticFile(x_sheafChatJsPath, roots);

  assert.ok(aguiJs);
  assert.ok(aguiCss);
  assert.ok(sheafCss);
  assert.ok(sheafJs);
  assert.match(aguiJs!.absolutePath, /agui-chat\.js$/);
  assert.match(sheafJs!.absolutePath, /sheaf-chat\.js$/);
  assert.ok(ResolveSheafChatIndexPath(repoRoot).endsWith("index.html"));
});

test("vendor allowlist resolves markdown-it, katex, and font assets", () =>
{
  const repoRoot = FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  const roots = BuildSheafChatStaticRoots(repoRoot);
  const vendorAllowlist = BuildVendorAssetAllowlist(repoRoot);
  const markdownIt = ResolveStaticFile(x_markdownItJsPath, roots, vendorAllowlist);
  const katexJs = ResolveStaticFile(x_katexJsPath, roots, vendorAllowlist);
  const katexCss = ResolveStaticFile(x_katexCssPath, roots, vendorAllowlist);

  assert.ok(markdownIt);
  assert.ok(katexJs);
  assert.ok(katexCss);
  assert.match(markdownIt!.absolutePath, /markdown-it\.min\.js$/);
  assert.match(katexJs!.absolutePath, /katex\.min\.js$/);

  const fontEntry = [...vendorAllowlist.entries()].find(([urlPath]) =>
    urlPath.startsWith(x_katexFontsUrlPrefix + "/"),
  );
  assert.ok(fontEntry);
  const fontResolved = ResolveStaticFile(fontEntry![0], roots, vendorAllowlist);
  assert.ok(fontResolved);
  assert.match(fontResolved!.absolutePath, /KaTeX_.*\.(woff2|woff|ttf)$/);
});

test("vendor routes reject path traversal", () =>
{
  const repoRoot = FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  const roots = BuildSheafChatStaticRoots(repoRoot);
  const vendorAllowlist = BuildVendorAssetAllowlist(repoRoot);

  assert.equal(
    ResolveStaticFile(`${x_katexFontsUrlPrefix}/../markdown-it.min.js`, roots, vendorAllowlist),
    undefined,
  );
  assert.equal(
    ResolveStaticFile("/assets/vendor/../../sheaf-chat/sheaf-chat.js", roots, vendorAllowlist),
    undefined,
  );
});

test("GET / serves the browser UI shell and static assets", async () =>
{
  const repoRoot = FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  const handle = await StartTestServer(repoRoot);

  try
  {
    const mainPage = await fetch(`${handle.baseUrl}/`);
    const mainHtml = await mainPage.text();
    assert.equal(mainPage.status, 200);
    assert.match(mainPage.headers.get("content-type") ?? "", /text\/html/);
    assert.match(mainHtml, /markdown-it\.min\.js/);
    assert.match(mainHtml, /katex\.min\.js/);
    assert.match(mainHtml, /sheaf-markdown\.js/);
    assert.match(mainHtml, /agui-chat\.js/);
    assert.match(mainHtml, /sheaf-chat\.js/);

    const markdownIt = await fetch(`${handle.baseUrl}${x_markdownItJsPath}`);
    assert.equal(markdownIt.status, 200);
    assert.match(markdownIt.headers.get("content-type") ?? "", /javascript/);

    const sheafMarkdown = await fetch(`${handle.baseUrl}${x_sheafMarkdownJsPath}`);
    assert.equal(sheafMarkdown.status, 200);
    assert.match(await sheafMarkdown.text(), /renderMarkdown/);

    const css = await fetch(`${handle.baseUrl}${x_sheafChatCssPath}`);
    assert.equal(css.status, 200);
    assert.match(css.headers.get("content-type") ?? "", /text\/css/);
    assert.match(await css.text(), /--sheaf-chat-touch/);

    const js = await fetch(`${handle.baseUrl}${x_sheafChatJsPath}`);
    assert.equal(js.status, 200);
    assert.match(js.headers.get("content-type") ?? "", /javascript/);
    assert.match(await js.text(), /RenderPilesScreen/);
  }
  finally
  {
    await handle.close();
  }
});

import { readdirSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { extname, join, normalize, sep } from "node:path";
import type { ServerResponse } from "node:http";

export type StaticAssetRoot =
{
  urlPrefix: string;
  rootDir: string;
};

export type StaticFileResult =
{
  content: Buffer;
  contentType: string;
};

const x_ContentTypes: Record<string, string> =
{
  ".css": "text/css; charset=utf-8",
  ".js": "application/javascript; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
  ".ttf": "font/ttf",
};

export const x_webAssetPrefix = "/assets/web";
export const x_sheafChatAssetPrefix = "/assets/sheaf-chat";
export const x_vendorAssetPrefix = "/assets/vendor";
export const x_aguiChatCssPath = `${x_webAssetPrefix}/agui-chat.css`;
export const x_aguiChatJsPath = `${x_webAssetPrefix}/agui-chat.js`;
export const x_sheafChatCssPath = `${x_sheafChatAssetPrefix}/sheaf-chat.css`;
export const x_sheafChatJsPath = `${x_sheafChatAssetPrefix}/sheaf-chat.js`;
export const x_sheafMarkdownJsPath = `${x_sheafChatAssetPrefix}/sheaf-markdown.js`;
export const x_markdownItJsPath = `${x_vendorAssetPrefix}/markdown-it.min.js`;
export const x_katexJsPath = `${x_vendorAssetPrefix}/katex.min.js`;
export const x_katexCssPath = `${x_vendorAssetPrefix}/katex.min.css`;
export const x_katexFontsUrlPrefix = `${x_vendorAssetPrefix}/katex/fonts`;

function NormalizeUrlPrefix(urlPrefix: string): string
{
  if (!urlPrefix.startsWith("/"))
  {
    throw new Error("static asset urlPrefix must start with /");
  }

  if (urlPrefix.length > 1 && urlPrefix.endsWith("/"))
  {
    return urlPrefix.slice(0, -1);
  }

  return urlPrefix;
}

function IsPathInsideRoot(rootDir: string, candidatePath: string): boolean
{
  const normalizedRoot = normalize(rootDir);
  const normalizedCandidate = normalize(candidatePath);

  if (normalizedCandidate === normalizedRoot)
  {
    return true;
  }

  return normalizedCandidate.startsWith(normalizedRoot + sep);
}

function ResolvePackageRoot(repoRoot: string): string
{
  return join(repoRoot, "projects", "sheaf-chat");
}

function ListKatexFontFileNames(packageRoot: string): string[]
{
  const fontsDir = join(packageRoot, "node_modules", "katex", "dist", "fonts");

  try
  {
    return readdirSync(fontsDir).filter((entry) =>
    {
      const extension = extname(entry).toLowerCase();
      return extension === ".woff" || extension === ".woff2" || extension === ".ttf";
    });
  }
  catch
  {
    return [];
  }
}

export function BuildVendorAssetAllowlist(repoRoot: string): Map<string, string>
{
  const packageRoot = ResolvePackageRoot(repoRoot);
  const nodeModulesDir = join(packageRoot, "node_modules");
  const allowlist = new Map<string, string>([
    [x_markdownItJsPath, join(nodeModulesDir, "markdown-it", "dist", "markdown-it.min.js")],
    [x_katexJsPath, join(nodeModulesDir, "katex", "dist", "katex.min.js")],
    [x_katexCssPath, join(nodeModulesDir, "katex", "dist", "katex.min.css")],
  ]);

  for (const fontFileName of ListKatexFontFileNames(packageRoot))
  {
    allowlist.set(
      `${x_katexFontsUrlPrefix}/${fontFileName}`,
      join(nodeModulesDir, "katex", "dist", "fonts", fontFileName),
    );
  }

  return allowlist;
}

export function BuildSheafChatStaticRoots(repoRoot: string): StaticAssetRoot[]
{
  return [
    {
      urlPrefix: x_webAssetPrefix,
      rootDir: join(repoRoot, "projects", "web", "src"),
    },
    {
      urlPrefix: x_sheafChatAssetPrefix,
      rootDir: join(repoRoot, "projects", "sheaf-chat", "src", "ui"),
    },
  ];
}

export function ResolveSheafChatIndexPath(repoRoot: string): string
{
  return join(repoRoot, "projects", "sheaf-chat", "src", "ui", "index.html");
}

export function ResolveVendorFile(
  urlPath: string,
  allowlist: Map<string, string>,
): { absolutePath: string; contentType: string } | undefined
{
  const fontsPrefix = x_katexFontsUrlPrefix + "/";

  if (urlPath.startsWith(fontsPrefix))
  {
    const relativePath = urlPath.slice(fontsPrefix.length);

    if (
      relativePath.length === 0 ||
      relativePath.includes("..") ||
      relativePath.includes("\\") ||
      relativePath.includes("/")
    )
    {
      return undefined;
    }

    const absolutePath = allowlist.get(urlPath);

    if (!absolutePath)
    {
      return undefined;
    }

    const extension = extname(absolutePath).toLowerCase();
    const contentType = x_ContentTypes[extension];

    if (!contentType)
    {
      return undefined;
    }

    return { absolutePath, contentType };
  }

  const absolutePath = allowlist.get(urlPath);

  if (!absolutePath)
  {
    return undefined;
  }

  const extension = extname(absolutePath).toLowerCase();
  const contentType = x_ContentTypes[extension];

  if (!contentType)
  {
    return undefined;
  }

  return { absolutePath, contentType };
}

export function ResolveStaticFile(
  urlPath: string,
  roots: StaticAssetRoot[],
  vendorAllowlist?: Map<string, string>,
): { absolutePath: string; contentType: string } | undefined
{
  if (vendorAllowlist)
  {
    const vendorResolved = ResolveVendorFile(urlPath, vendorAllowlist);

    if (vendorResolved)
    {
      return vendorResolved;
    }
  }

  for (const root of roots)
  {
    const urlPrefix = NormalizeUrlPrefix(root.urlPrefix);

    if (urlPath === urlPrefix || !urlPath.startsWith(urlPrefix + "/"))
    {
      continue;
    }

    const relativePath = urlPath.slice(urlPrefix.length + 1);

    if (relativePath.includes("..") || relativePath.includes("\\"))
    {
      return undefined;
    }

    const absolutePath = normalize(join(root.rootDir, relativePath));

    if (!IsPathInsideRoot(root.rootDir, absolutePath))
    {
      return undefined;
    }

    const extension = extname(absolutePath).toLowerCase();
    const contentType = x_ContentTypes[extension];

    if (!contentType)
    {
      return undefined;
    }

    return { absolutePath, contentType };
  }

  return undefined;
}

export async function ReadStaticFile(
  urlPath: string,
  roots: StaticAssetRoot[],
  vendorAllowlist?: Map<string, string>,
): Promise<StaticFileResult | undefined>
{
  const resolved = ResolveStaticFile(urlPath, roots, vendorAllowlist);

  if (!resolved)
  {
    return undefined;
  }

  const content = await readFile(resolved.absolutePath);

  return {
    content,
    contentType: resolved.contentType,
  };
}

export function SendBytes(
  response: ServerResponse,
  statusCode: number,
  contentType: string,
  content: Buffer,
): void
{
  response.statusCode = statusCode;
  response.setHeader("Content-Type", contentType);
  response.setHeader("Content-Length", content.length);
  response.end(content);
}

export function SendHtml(response: ServerResponse, html: string): void
{
  const content = Buffer.from(html, "utf-8");
  SendBytes(response, 200, "text/html; charset=utf-8", content);
}

export function SendStaticResult(response: ServerResponse, result: StaticFileResult): void
{
  SendBytes(response, 200, result.contentType, result.content);
}

/**
 * Shared Markdown-it/KaTeX rendering and safe file-link resolution for Sheaf chat.
 */
(function () {
  "use strict";

  const x_MarkdownExtensions = [".md", ".markdown"];
  const x_SheafFilePrefix = "sheaf-file:";
  const x_MathPlaceholderPrefix = "[[[SHEAF_MATH_";
  const x_MathPlaceholderSuffix = "]]]";

  let m_md = null;

  function IsMarkdownPath(pathValue) {
    const lower = String(pathValue).toLowerCase();
    for (let index = 0; index < x_MarkdownExtensions.length; index += 1) {
      if (lower.endsWith(x_MarkdownExtensions[index])) {
        return true;
      }
    }
    return false;
  }

  function SplitFragment(href) {
    const hashIndex = href.indexOf("#");
    if (hashIndex < 0) {
      return { target: href, fragment: undefined };
    }
    return {
      target: href.slice(0, hashIndex),
      fragment: href.slice(hashIndex + 1) || undefined,
    };
  }

  function DecodePathValue(pathValue) {
    let decoded = pathValue;

    try {
      decoded = decodeURIComponent(pathValue.replace(/\+/g, " "));
    } catch (_error) {
      return null;
    }

    if (decoded.indexOf("\0") >= 0) {
      return null;
    }

    return decoded.replace(/\\/g, "/");
  }

  function DecodePathSegments(pathValue) {
    const decodedPath = DecodePathValue(pathValue);

    if (!decodedPath) {
      return null;
    }

    const segments = decodedPath.split("/").filter(function (segment) {
      return segment.length > 0;
    });
    const normalized = [];

    for (let index = 0; index < segments.length; index += 1) {
      const segment = segments[index];
      if (segment === ".") {
        continue;
      }
      if (segment === "..") {
        return null;
      }

      normalized.push(segment);
    }

    return normalized.join("/");
  }

  function ResolveRelativePath(basePath, relativePath) {
    const baseParts = basePath.split("/");
    if (baseParts.length > 0) {
      baseParts.pop();
    }

    const decodedRelative = DecodePathValue(relativePath);

    if (!decodedRelative) {
      return null;
    }

    const relativeParts = decodedRelative.split("/");
    const combined = baseParts.concat(relativeParts).join("/");
    return DecodePathSegments(combined);
  }

  function HasProtocol(target) {
    return /^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(target);
  }

  function ResolveSheafFileTarget(target) {
    if (!target.startsWith(x_SheafFilePrefix)) {
      return null;
    }

    const relativePath = target.slice(x_SheafFilePrefix.length).replace(/^\/+/, "");
    return DecodePathSegments(relativePath);
  }

  function ResolveFileLink(href, basePath, _rootMode) {
    if (href == null || typeof href !== "string") {
      return null;
    }

    const trimmed = href.trim();
    if (trimmed.length === 0) {
      return null;
    }

    const split = SplitFragment(trimmed);
    const target = split.target;
    const fragment = split.fragment;

    if (target.indexOf("\\") >= 0 || target.indexOf("\0") >= 0) {
      return null;
    }

    if (target.startsWith("//")) {
      return null;
    }

    if (target.startsWith("/") && (target.length === 1 || target.charAt(1) === "/")) {
      return null;
    }

    let resolved = null;

    const sheafFilePath = ResolveSheafFileTarget(target);
    if (sheafFilePath != null) {
      resolved = sheafFilePath;
    } else if (HasProtocol(target)) {
      return null;
    } else if (target.startsWith("/")) {
      resolved = DecodePathSegments(target.replace(/^\/+/, ""));
    } else if (basePath) {
      resolved = ResolveRelativePath(basePath, target);
    } else {
      return null;
    }

    if (!resolved || resolved.length === 0) {
      return null;
    }

    if (resolved.charAt(0) === "/" || /^[a-zA-Z]:[\\/]/.test(resolved)) {
      return null;
    }

    if (!IsMarkdownPath(resolved)) {
      return null;
    }

    if (fragment != null) {
      return { path: resolved, fragment: fragment };
    }

    return { path: resolved };
  }

  function RenderKatex(tex, displayMode) {
    if (typeof katex === "undefined" || !katex.renderToString) {
      return null;
    }

    try {
      return katex.renderToString(tex, {
        displayMode: displayMode === true,
        throwOnError: false,
      });
    } catch (_error) {
      return null;
    }
  }

  function ProtectMath(markdown, placeholders) {
    let working = markdown;

    function ProtectPattern(pattern, displayMode) {
      working = working.replace(pattern, function (match, tex) {
        const rendered = RenderKatex(String(tex).trim(), displayMode);
        const index = placeholders.length;
        placeholders.push(
          rendered != null
            ? '<span class="sheaf-markdown-math' +
                (displayMode ? " sheaf-markdown-math--display" : "") +
                '">' +
                rendered +
                "</span>"
            : match
        );
        return x_MathPlaceholderPrefix + index + x_MathPlaceholderSuffix;
      });
    }

    ProtectPattern(/\$\$([\s\S]+?)\$\$/g, true);
    ProtectPattern(/\\\[([\s\S]+?)\\\]/g, true);
    ProtectPattern(/\\\(([\s\S]+?)\\\)/g, false);
    working = working.replace(
      /(^|[^\\])\$([^$\n]+?)\$(?!\$)/g,
      function (match, prefix, tex) {
        const rendered = RenderKatex(String(tex).trim(), false);
        const index = placeholders.length;
        placeholders.push(
          rendered != null
            ? '<span class="sheaf-markdown-math">' + rendered + "</span>"
            : match
        );
        return prefix + x_MathPlaceholderPrefix + index + x_MathPlaceholderSuffix;
      }
    );

    return working;
  }

  function RestoreMath(html, placeholders) {
    let restored = html;
    for (let index = 0; index < placeholders.length; index += 1) {
      const token = x_MathPlaceholderPrefix + index + x_MathPlaceholderSuffix;
      restored = restored.split(token).join(placeholders[index]);
    }
    return restored;
  }

  function GetMarkdownIt() {
    if (m_md) {
      return m_md;
    }

    if (typeof markdownit === "undefined") {
      return null;
    }

    m_md = markdownit({
      html: false,
      linkify: true,
      breaks: false,
    });

    return m_md;
  }

  function RenderMarkdown(markdown, _options) {
    const source = markdown != null ? String(markdown) : "";
    const md = GetMarkdownIt();

    if (!md) {
      return null;
    }

    const placeholders = [];
    const protectedSource = ProtectMath(source, placeholders);
    const rendered = md.render(protectedSource);
    const withMath = RestoreMath(rendered, placeholders);

    return '<div class="sheaf-markdown">' + withMath + "</div>";
  }

  function EnhanceRenderedLinks(container, context) {
    if (!container || !container.querySelectorAll) {
      return;
    }

    const opts = context || {};
    const links = container.querySelectorAll("a[href]");

    for (let index = 0; index < links.length; index += 1) {
      const link = links[index];
      const href = link.getAttribute("href");
      const resolved = ResolveFileLink(href, opts.basePath, opts.rootMode);

      if (!resolved || typeof opts.onFileLink !== "function") {
        continue;
      }

      link.classList.add("sheaf-markdown-file-link");
      link.addEventListener("click", function (event) {
        event.preventDefault();
        opts.onFileLink(resolved.path, resolved.fragment);
      });
    }
  }

  const SheafMarkdown = {
    renderMarkdown: RenderMarkdown,
    enhanceRenderedLinks: EnhanceRenderedLinks,
    resolveFileLink: ResolveFileLink,
    _test: {
      decodePathSegments: DecodePathSegments,
      isMarkdownPath: IsMarkdownPath,
      protectMath: ProtectMath,
      restoreMath: RestoreMath,
      resolveRelativePath: ResolveRelativePath,
    },
  };

  if (typeof globalThis !== "undefined") {
    globalThis.SheafMarkdown = SheafMarkdown;
  }
  if (typeof window !== "undefined") {
    window.SheafMarkdown = SheafMarkdown;
  }
})();

